var klaroConfig={elementID:'klaro',lang:'de',default:false,acceptAll:true,callback:function(manager,service){if(service==='googleMaps'){location.reload();}},translations:{de:{consentModal:{title:'Datenschutz & Cookies',description:'Wir nutzen auf dieser Website zwei externe Dienste: Google Maps für die Anfahrtskarten und Open-Meteo für die Wettervorhersage. Beide werden erst geladen, wenn du zustimmst.',},consentNotice:{description:'Wir nutzen Google Maps für die Anfahrt und Open-Meteo für die Wettervorhersage. Beides lädt erst mit deiner Zustimmung.',learnMore:'Einstellungen anpassen',},ok:'Alles akzeptieren',decline:'Ablehnen',googleMaps:{description:'Anzeige von interaktiven Karten.',},wetter:{description:'Wettervorhersage für Trainings- und Veranstaltungsorte.',},purposes:{functional:'Funktionale Dienste',}}},services:[{name:'googleMaps',default:false,title:'Google Maps',purposes:['functional'],onAccept:(status)=>{if(status===true&&typeof window.loadGoogleMap==='function'){window.loadGoogleMap();}}},{name:'wetter',default:false,title:'Wettervorhersage (Open-Meteo)',purposes:['functional'],onAccept:(status)=>{if(status===true&&typeof window.ladeWetter==='function'){window.ladeWetter();}}}]};document.addEventListener('DOMContentLoaded',function(){function fixKlaroDialogName(){document.querySelectorAll('[role="dialog"]').forEach(function(dialog){var labelId=dialog.getAttribute('aria-labelledby');var labelEl=labelId?document.getElementById(labelId):null;if(!labelEl||!labelEl.textContent.trim()){dialog.removeAttribute('aria-labelledby');dialog.setAttribute('aria-label','Cookie-Einstellungen');}});}
var klaroObserver=new MutationObserver(fixKlaroDialogName);klaroObserver.observe(document.body,{childList:true,subtree:true});fixKlaroDialogName();});